/**
 * Spanish translation overrides and UI translation helper.
 * Full key coverage loaded from spanish-data.json (generated by build-spanish-data.js).
 */
const fs = require('fs');
const path = require('path');

const DATA_PATH = path.join(__dirname, 'spanish-data.json');
let SPANISH_OVERRIDES = {};
if (fs.existsSync(DATA_PATH)) {
  SPANISH_OVERRIDES = JSON.parse(fs.readFileSync(DATA_PATH, 'utf8'));
}

/** Quality UI translation for keys not in overrides */
function translateUI(key, english) {
  if (!english) return key;

  // Pass through if already looks Spanish
  if (/^[¿¡]/.test(english) || /\b(por favor|error|guardar|cancelar)\b/i.test(english)) {
    return english;
  }

  const section = key.split('.')[0];

  // Common exact matches
  const EXACT = {
    'OK': 'Aceptar',
    'Error': 'Error',
    'Success': 'Éxito',
    'Loading...': 'Cargando...',
    'Cancel': 'Cancelar',
    'Save': 'Guardar',
    'Continue': 'Continuar',
    'Back': 'Atrás',
    'Next': 'Siguiente',
    'Done': 'Hecho',
    'Retry': 'Reintentar',
    'Skip': 'Omitir',
    'Share': 'Compartir',
    'Delete': 'Eliminar',
    'Sign In': 'Iniciar sesión',
    'Sign Out': 'Cerrar sesión',
    'Settings': 'Ajustes',
    'Profile': 'Perfil',
    'Home': 'Inicio',
    'Chat': 'Chat',
    'Free': 'Gratis',
    'Processing...': 'Procesando...',
    'Got it!': '¡Entendido!',
    'Got it': 'Entendido',
    'Thank you!': '¡Gracias!',
    'Thank You!': '¡Gracias!',
    'Noted': 'Anotado',
    'now': 'ahora',
    'Vote': 'Votar',
  };
  if (EXACT[english]) return EXACT[english];

  // Pattern-based quality translations
  let s = english;

  const patterns = [
    [/^Please (.+)$/i, 'Por favor, $1'],
    [/^Failed to (.+?)\.? Please try again\.?$/i, 'No se pudo $1. Por favor, inténtalo de nuevo.'],
    [/^Failed to (.+)$/i, 'Error al $1'],
    [/^Could not (.+?)\.? Please try again\.?$/i, 'No se pudo $1. Por favor, inténtalo de nuevo.'],
    [/^Could not (.+)$/i, 'No se pudo $1'],
    [/^Are you sure you want to (.+)\?$/i, '¿Estás seguro de que quieres $1?'],
    [/^Sign in to (.+)$/i, 'Inicia sesión para $1'],
    [/^You must be logged in to (.+)$/i, 'Debes iniciar sesión para $1'],
    [/^Permission [Rr]equired$/i, 'Permiso necesario'],
    [/^(.+) is required$/i, '$1 es obligatorio'],
    [/^Loading (.+)$/i, 'Cargando $1'],
    [/^(.+) saved successfully\.?$/i, '$1 guardado correctamente.'],
    [/^Your (.+) has been (.+)$/i, 'Tu $1 ha sido $2'],
    [/^No (.+) yet$/i, 'Aún no hay $1'],
    [/^Search (.+)$/i, 'Buscar $1'],
    [/^Add (.+)$/i, 'Añadir $1'],
    [/^Delete (.+)$/i, 'Eliminar $1'],
    [/^Manage (.+)$/i, 'Gestionar $1'],
    [/^Upgrade to (.+)$/i, 'Mejorar a $1'],
    [/^Restore [Pp]urchases$/i, 'Restaurar compras'],
    [/^Terms of Service$/i, 'Términos de servicio'],
    [/^Privacy Policy$/i, 'Política de privacidad'],
    [/^Help & FAQ$/i, 'Ayuda y preguntas frecuentes'],
    [/^Send [Ff]eedback$/i, 'Enviar comentarios'],
    [/^Most [Pp]opular$/i, 'Más popular'],
    [/^Current [Pp]lan$/i, 'Plan actual'],
    [/^per month$/i, 'al mes'],
    [/^per year$/i, 'al año'],
    [/^Save (\d+)%$/i, 'Ahorra $1%'],
  ];

  for (const [re, repl] of patterns) {
    if (re.test(s)) {
      s = s.replace(re, repl);
      break;
    }
  }

  // Word-level fashion/app glossary
  const GLOSSARY = {
    wardrobe: 'armario',
    outfit: 'outfit',
    outfits: 'outfits',
    stylist: 'estilista',
    subscription: 'suscripción',
    settings: 'ajustes',
    profile: 'perfil',
    account: 'cuenta',
    password: 'contraseña',
    email: 'correo electrónico',
    photo: 'foto',
    photos: 'fotos',
    camera: 'cámara',
    upload: 'subir',
    download: 'descargar',
    upgrade: 'mejorar plan',
    plan: 'plan',
    free: 'gratis',
    premium: 'premium',
    features: 'funciones',
    feedback: 'comentarios',
    support: 'soporte',
    help: 'ayuda',
    community: 'comunidad',
    challenge: 'reto',
    voting: 'votación',
    calendar: 'calendario',
    lookbook: 'lookbook',
    measurements: 'medidas',
    shopping: 'compras',
    browse: 'explorar',
    discover: 'descubrir',
    notifications: 'notificaciones',
    privacy: 'privacidad',
    billing: 'facturación',
    purchase: 'compra',
    purchases: 'compras',
    restore: 'restaurar',
    cancel: 'cancelar',
    paused: 'en pausa',
    active: 'activo',
    unlimited: 'ilimitado',
    voice: 'voz',
    credits: 'créditos',
    monthly: 'mensual',
    yearly: 'anual',
    annually: 'anualmente',
  };

  // Apply glossary for simple humanized strings
  if (section !== 'terms' && section !== 'privacy') {
    for (const [en, es] of Object.entries(GLOSSARY)) {
      s = s.replace(new RegExp(`\\b${en}\\b`, 'gi'), (m) =>
        m[0] === m[0].toUpperCase() ? es.charAt(0).toUpperCase() + es.slice(1) : es
      );
    }
  }

  return s;
}

module.exports = { SPANISH_OVERRIDES, translateUI };
